import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e,a,b as t}from"./chunks/M-S-SY3.DDtr6WYL.js";import{_ as r,o as n,c as s,a3 as c}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Copia impostazioni","description":"","frontmatter":{"source_hash":"68f7c3719c","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/copysettings.md","filePath":"it/use/copysettings.md"}'),p={name:"it/use/copysettings.md"};function l(d,i,m,u,f,g){return n(),s("div",null,[...i[0]||(i[0]=[c('<p>xDrip offre un modo semplice per copiare le impostazioni da un telefono all&#39;altro.</p><h3 id="show-settings-qr-code" tabindex="-1">Mostra impostazioni dei codici QR <a class="header-anchor" href="#show-settings-qr-code" aria-label="Permalink to &quot;Mostra impostazioni dei codici QR {#show-settings-qr-code}&quot;">​</a></h3><p>Mostra impostazioni dei codici QR visualizza un codice QR che contiene le impostazioni di xDrip.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrcode_grey600_48dp.png" style="width:5%;"> Mostra impostazioni dei codici QR</p></div><div class="admonition xdrip"><p class="admonition-title">Condividi impostazioni tramite il codice QR</p><p> Utilizzare i codici QR per trasferire le impostazioni utilizzando Impostazioni-&gt; Configurazione automatica caratteristica</p></div><p>La chiave di sicurezza di xDrip è usata per xDrip Sync: se vuoi condividere solo un codice follower (difficile da copiare a mano), usa questa opzione.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  SOLO IMPOSTAZIONI USANDO XDRIP PLUS SECURITY KEY </div></p></div><p>Se hai usato codici QR di personalizzazione per xDrip su questo telefono (G7, 1+, BlueJay, ...), puoi trasferirli direttamente su un altro telefono.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  EXPORT KEKS KEY TO ANOTHER PHONE </div></p></div><p>Le impostazioni generali e di raccolta comprendono le impostazioni generali e quelle della sorgente dati hardware.</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  VISUALIZZA IMPOSTAZIONI TRASFERIMENTO DATI E IMPOSTAZIONI GENERALI </div></p></div><p>Tutte le impostazioni comprendono tutto (tranne gli allarmi: devi ricrearli a mano).</p><div class="admonition xdrip"><p class="admonition-title"><div style="background-color:gray;color:white;text-align:center;">  COPIARE TUTTE LE IMPOSTAZIONI </div></p></div><p>Otterrai un codice QR da scansionare con Configurazione automatica su un altro telefono.</p><img src="'+e+'" style="zoom:75%;"><h3 id="auto-configure" tabindex="-1">Configurazione automatica <a class="header-anchor" href="#auto-configure" aria-label="Permalink to &quot;Configurazione automatica {#auto-configure}&quot;">​</a></h3><p>Configurazione automatica ti permette di importare le impostazioni da un codice QR.</p><p>Assicurati che il codice QR che stai per scansionare provenga da una fonte sicura.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_qrscan.png" style="width:5%;"> Configurazione automatica</p></div><h4 id="camera" tabindex="-1">Camera <a class="header-anchor" href="#camera" aria-label="Permalink to &quot;Camera {#camera}&quot;">​</a></h4><div class="admonition xdripitem"><p class="admonition-title">Camera</p><p> Scansiona un codice QR con il tuo cellulare (consigliato)</p></div><p>Devi autorizzare xDrip ad accedere alla fotocamera del telefono.</p><p>Puoi poi scansionare il codice QR mostrato su un altro telefono per copiare le impostazioni che hai selezionato quando l&#39;hai visualizzato, come spiegato <a href="#show-settings-qr-code">sopra</a>.</p><img src="'+a+'" style="zoom:75%;"><p>Le impostazioni attuali verranno sovrascritte: verrà mostrato un elenco da confermare.</p><div class="admonition xdripitem"><p class="admonition-title">Sei sicuro?</p><p> Importa solo le impostazioni da fonti affidabili!<br>  Conferma di volere importare le impostazioni seguenti:</p><p> impostazione1<br>  impostazione2<br>  impostazione3</p><p> No     Si</p></div><p>Un codice QR <em>Copiare tutte le Impostazioni</em> non contiene le impostazioni stesse: xDrip le scarica dopo la tua conferma. Dalla release 2026.11.21 ti viene chiesto prima di confermare.</p><div class="admonition xdripitem"><p class="admonition-title">Sei sicuro?</p><p> Only import settings from sources you trust!<br>  Please confirm to download and import all settings from this code.</p></div><p>Potrebbe essere necessario riavviare il telefono per applicare le modifiche.</p><h4 id="image-file" tabindex="-1">File immagine <a class="header-anchor" href="#image-file" aria-label="Permalink to &quot;File immagine {#image-file}&quot;">​</a></h4><p>Se il tuo telefono ha una fotocamera di scarsa qualità o non ne ha affatto, puoi caricare il codice QR da un file.</p><p>Prima devi salvare tra le tue immagini l&#39;immagine del codice QR da scansionare.</p><div class="admonition xdripitem"><p class="admonition-title">File immagine</p><p> Puoi salvare un codice QR come un file immagine (come .png o .jpeg) sul tuo cellulare. Quindi, utilizzare questa opzione per scansionare il codice QR dal file salvato.</p></div><p>Seleziona l&#39;immagine che contiene il codice QR.</p><img src="'+t+'" style="zoom:75%;"><p>Le impostazioni attuali verranno sovrascritte: verrà mostrato un elenco da confermare.</p><div class="admonition xdripitem"><p class="admonition-title">Sei sicuro?</p><p> Importa solo le impostazioni da fonti affidabili!<br>  Conferma di volere importare le impostazioni seguenti:</p><p> impostazione1<br>  impostazione2<br>  impostazione3</p><p> No     Si</p></div><p>Potrebbe essere necessario riavviare il telefono per applicare le modifiche.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',40)])])}const x=r(p,[["render",l]]);export{_ as __pageData,x as default};
